	@Test
	@SuppressWarnings("unchecked")
	void compatibilityWrappersCloseRawDelegateExactlyOnceOnEarlyClose() {
		assertAll(List.of(false, true).stream().map(indexed -> () -> {
			CloseableIteration<BindingSet> raw = mock(CloseableIteration.class);
			when(raw.hasNext()).thenReturn(true);
			when(raw.next()).thenReturn(indexed ? binding("x", PREDICATE, "__rowIdx", VF.createLiteral(0))
					: binding("x", PREDICATE));
			BindingSet input = binding("x", PREDICATE);
			try (CloseableIteration<BindingSet> rows = indexed
					? new ServiceJoinConversionIteration(raw, List.of(input))
					: new InsertBindingSetCursor(raw, input)) {
				assertTrue(rows.hasNext());
				rows.next();
			}
			verify(raw).close();
		}));
	}

	@Test
	@SuppressWarnings("unchecked")
	void compatibilityWrappersCloseRawDelegateExactlyOnceWhenPredicateFails() {
		assertAll(List.of(false, true).stream().map(indexed -> () -> {
			CloseableIteration<BindingSet> raw = mock(CloseableIteration.class);
			when(raw.hasNext()).thenReturn(true);
			QueryEvaluationException failure = new QueryEvaluationException("compatibility predicate failed");
			BindingSet broken = mock(BindingSet.class);
			when(broken.isEmpty()).thenReturn(false);
			when(broken.getBinding("x")).thenThrow(failure);
			when(broken.getValue("__rowIdx")).thenThrow(failure);
			when(raw.next()).thenReturn(broken);
			BindingSet input = binding("x", PREDICATE);
			try (CloseableIteration<BindingSet> rows = indexed
					? new ServiceJoinConversionIteration(raw, List.of(input))
					: new InsertBindingSetCursor(raw, input)) {
				assertSame(failure, assertThrows(QueryEvaluationException.class, rows::hasNext));
			}
			verify(raw).close();
		}));
	}

